from __future__ import annotations

from exo import *
from exo.libs.memories import DRAM
from exo.API_scheduling import *


# Baseline LUDCMP kernel matching the PolyBench reference.
@proc
def kernel_ludcmp(
    n: size,
    A: DATA_TYPE[n, n] @ DRAM,
    b: DATA_TYPE[n] @ DRAM,
    x: DATA_TYPE[n] @ DRAM,
    y: DATA_TYPE[n] @ DRAM,
):
    w: DATA_TYPE

    # LU decomposition (Doolittle, no pivoting), in-place on A.
    for i in seq(0, n):
        # Compute L entries A[i, j] for j <= i (strictly lower plus diagonal).
        for j in seq(0, i):
            w = A[i, j]
            for k in seq(0, j):
                w = w - A[i, k] * A[k, j]
            A[i, j] = w / A[j, j]

        # Compute U entries A[i, j] for j >= i (upper triangular, including diagonal).
        for j in seq(i, n):
            w = A[i, j]
            for k in seq(0, i):
                w = w - A[i, k] * A[k, j]
            A[i, j] = w

    # Forward substitution to solve L * y = b.
    for i in seq(0, n):
        w = b[i]
        for j in seq(0, i):
            w = w - A[i, j] * y[j]
        y[i] = w

    # Backward substitution to solve U * x = y.
    # Original C code:
    #   for (i = n-1; i >= 0; i--) {
    #     w = y[i];
    #     for (j = i+1; j < n; j++)
    #       w -= A[i][j] * x[j];
    #     x[i] = w / A[i][i];
    #   }
    #
    # Here we iterate i forward with i0 = n - 1 - i, keeping j in ascending order.
    for i in seq(0, n):
        # i0 = n - 1 - i
        w = y[n - 1 - i]
        for j in seq(n - i, n):
            # j runs from i0 + 1 up to n-1.
            w = w - A[n - 1 - i, j] * x[j]
        x[n - 1 - i] = w / A[n - 1 - i, n - 1 - i]


# ---------------------------------------------------------------------------
# Scheduling: improve cache locality and expose parallelism in the U-update.
# ---------------------------------------------------------------------------

# Tile size for the U-update loop in the j dimension. This is a compile-time
# tuning knob; 32 is a reasonable default for modern x86 L1/L2 caches.
TILE_J = 32

p = kernel_ludcmp

# Canonicalize expressions and remove trivial dead code before scheduling.
p = simplify(p)

# 1) Locate the outermost i loop that performs the LU factorization.
lu_i = p.find_loop("i")  # This is the first 'for i in seq(0, n)'.

# 2) Inside that loop, pick the second j loop:
#    - j #0:  L update, j in [0, i)
#    - j #1:  U update, j in [i, n)
u_j = lu_i.body().find_loop("j #1")

# 3) Shift the U-update j loop to start from 0 so we can tile it easily.
#    for j in seq(i, n) --> for j in seq(0, n - i)
#    All uses of j inside the loop are rewritten as (j + i).
p = shift_loop(p, u_j, "0")

# Re-acquire the loop cursors after the transformation.
lu_i = p.find_loop("i")
u_j = lu_i.body().find_loop("j #1")

